cd /app; cat > /tmp/probe.rb <<'EOF'
t = Time.utc(2024, 6, 19, 20, 2, 28)
tz = ActiveSupport::TimeWithZone.new(t, Time.find_zone("UTC"))
def try(label)
  r = yield
  puts "#{label} => #{r.inspect}"
rescue => e
  puts "#{label} !! #{e.class}: #{e.message}"
end
try("Date#to_s(:long)")          { t.to_date.to_s(:long) }
try("Date#to_fs(:long)")         { t.to_date.to_fs(:long) }
try("Date#to_fs(:short)")        { t.to_date.to_fs(:short) }
try("TZ#to_s(:number)")          { tz.to_s(:number) }
try("TZ#to_fs(:number)")         { tz.to_fs(:number) }
try("TZ#to_fs(:long)")           { tz.to_fs(:long) }
try("TZ#to_fs(:short)")          { tz.to_fs(:short) }
try("TZ#to_default_s")           { tz.to_default_s }
try("TZ#to_s")                   { tz.to_s }
try("Time#to_default_s")         { t.to_default_s }
try("Time#to_s")                 { t.to_s }
try("Array#to_s(:db) []")        { [].to_s(:db) }
try("Array#to_fs(:db) []")       { [].to_fs(:db) }
try("Integer#to_s(:delimited)")  { 1234567.to_s(:delimited) }
try("NumberHelper delimited")    { ActiveSupport::NumberHelper.number_to_delimited(1234567) }
try("Integer#to_fs")             { 1.to_fs }
p Integer.instance_method(:to_s).owner, Date.instance_method(:to_s).owner, Time.instance_method(:to_s).owner
EOF
RAILS_ENV=test timeout 300 bin/rails runner /tmp/probe.rb 2>&1 | grep -v "warning\|DEPRECATION\|benchmark"

